<?php
namespace Tests\Feature;

use App\Enums\{CrmAssignmentMode,CrmInquirySource,CrmRequirementType,OpportunityLostReason,OpportunityType};
use App\Models\{Company,CompanySetting,CrmPipelineStage,CrmStageRequirement,Lead,Listing,Opportunity,User};
use App\Services\{LeadIntakeService,OpportunityService,OpportunityWorkflowService};
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Validation\ValidationException;
use Spatie\Permission\Models\Permission;
use Tests\TestCase;

class CrmWorkflowTest extends TestCase
{
 use RefreshDatabase;
 private function company(string $name): Company { return Company::create(['name'=>$name,'email'=>strtolower(str_replace(' ','',$name)).'@test.local']); }
 private function user(Company $company,array $permissions=[]): User { $user=User::factory()->create(['company_id'=>$company->id]); foreach($permissions as $permission)$user->givePermissionTo(Permission::findOrCreate($permission,'web')); return $user; }
 private function permissions(): array { return ['view_any_lead','view_lead','create_lead','update_lead','assign_lead','view_any_opportunity','view_opportunity','create_opportunity','update_opportunity','assign_opportunity','move_opportunity_stage','close_won_opportunity','close_lost_opportunity']; }
 private function intake(User $actor,array $data=[]): array { return app(LeadIntakeService::class)->intake($actor,array_merge(['name'=>'Ahmad','phone'=>'0591234567','source'=>CrmInquirySource::Manual->value],$data)); }
 private function opportunity(User $actor,Lead $lead,array $data=[]): Opportunity { return app(OpportunityService::class)->create($actor,array_merge(['lead_id'=>$lead->id,'type'=>OpportunityType::Sale->value,'source'=>CrmInquirySource::Manual->value],$data)); }
 public function test_deduplicates_phone_and_email_only_inside_company_without_auto_merge_conflicts(): void { $a=$this->company('A');$b=$this->company('B');$actor=$this->user($a,$this->permissions());$first=$this->intake($actor,['email'=>'A@EXAMPLE.TEST']);$duplicate=$this->intake($actor,['name'=>'Ahmad Two','phone'=>'+970 59 123 4567']);$this->assertTrue($duplicate['duplicate']);$this->assertSame($first['lead']->id,$duplicate['lead']->id);$other=$this->user($b,$this->permissions());$separate=$this->intake($other,['email'=>'a@example.test']);$this->assertNotSame($first['lead']->id,$separate['lead']->id);$this->intake($actor,['name'=>'Phone Lead','phone'=>'0599999999','email'=>'phone@test.local']);$this->intake($actor,['name'=>'Email Lead','phone'=>'0598888888','email'=>'email@test.local']);$this->expectException(ValidationException::class);$this->intake($actor,['phone'=>'0599999999','email'=>'email@test.local']); }
 public function test_generic_inquiry_has_no_opportunity_and_listing_inquiry_creates_new_opportunity(): void { $company=$this->company('A');$actor=$this->user($company,$this->permissions());$generic=$this->intake($actor);$this->assertNull($generic['opportunity']);$listing=Listing::withoutGlobalScopes()->create(['company_id'=>$company->id,'listable_type'=>'unit','listable_id'=>1,'listing_type'=>'sale','title'=>'A-101','asking_price'=>100000,'currency'=>'USD','created_by'=>$actor->id]);$specific=$this->intake($actor,['phone'=>'0595555555','listing_id'=>$listing->id]);$this->assertNotNull($specific['opportunity']);$this->assertSame($listing->id,$specific['opportunity']->listing_id);$this->assertSame('new',$specific['opportunity']->stage->code); }
 public function test_lead_and_opportunity_owners_are_independent_and_cross_company_assignment_is_rejected(): void { $company=$this->company('A');$other=$this->company('B');$actor=$this->user($company,$this->permissions());$leadOwner=$this->user($company);$opportunityOwner=$this->user($company);$lead=app(LeadIntakeService::class)->createLead($actor,['name'=>'Owner Lead','phone'=>'0592222222','assigned_to'=>$leadOwner->id]);$opportunity=$this->opportunity($actor,$lead,['assigned_to'=>$opportunityOwner->id]);$this->assertSame($leadOwner->id,$lead->assigned_to);$this->assertSame($opportunityOwner->id,$opportunity->assigned_to);$this->expectException(ValidationException::class);app(OpportunityService::class)->assign($actor,$opportunity,$this->user($other)->id); }
 public function test_manual_round_robin_and_unassigned_queue_assignment_modes(): void { $company=$this->company('A');$actor=$this->user($company,$this->permissions());$second=$this->user($company);CompanySetting::withoutGlobalScopes()->create(['company_id'=>$company->id,'crm_assignment_mode'=>CrmAssignmentMode::RoundRobin->value]);$one=app(LeadIntakeService::class)->createLead($actor,['name'=>'One','phone'=>'0593000001']);$two=app(LeadIntakeService::class)->createLead($actor,['name'=>'Two','phone'=>'0593000002']);$this->assertNotSame($one->assigned_to,$two->assigned_to);CompanySetting::withoutGlobalScopes()->where('company_id',$company->id)->update(['crm_assignment_mode'=>CrmAssignmentMode::UnassignedQueue->value]);$queue=app(LeadIntakeService::class)->createLead($actor,['name'=>'Queue','phone'=>'0593000003']);$this->assertNull($queue->assigned_to); }
 public function test_pipeline_defaults_stage_label_customization_and_protected_kanban_workflow(): void { $company=$this->company('A');$actor=$this->user($company,$this->permissions());$lead=$this->intake($actor)['lead'];$opportunity=$this->opportunity($actor,$lead);$pipeline=$opportunity->pipeline;$this->assertCount(7,$pipeline->stages);$contacted=$pipeline->stages()->where('code','contacted')->firstOrFail();$contacted->update(['label'=>'Reach out']);$moved=app(OpportunityWorkflowService::class)->moveToStage($actor,$opportunity,$contacted);$this->assertSame($contacted->id,$moved->pipeline_stage_id);$qualified=$pipeline->stages()->where('code','qualified')->firstOrFail();$this->expectException(ValidationException::class);app(OpportunityWorkflowService::class)->moveToStage($actor,$moved,$qualified); }
 public function test_kanban_move_writes_history_and_won_lost_are_terminal(): void { $company=$this->company('A');$actor=$this->user($company,$this->permissions());$lead=$this->intake($actor,['contact_result'=>'called'])['lead'];$opportunity=$this->opportunity($actor,$lead);$pipeline=$opportunity->pipeline;$contacted=$pipeline->stages()->where('code','contacted')->firstOrFail();$moved=app(OpportunityWorkflowService::class)->moveToStage($actor,$opportunity,$contacted);$this->assertSame($contacted->id,$moved->pipeline_stage_id);$lost=$pipeline->stages()->where('code','lost')->firstOrFail();$closed=app(OpportunityWorkflowService::class)->moveToStage($actor,$moved,$lost,['lost_reason'=>OpportunityLostReason::NoResponse->value]);$this->assertNotNull($closed->closed_at);$this->assertSame(OpportunityLostReason::NoResponse,$closed->lost_reason);$this->assertSame(3,$closed->stageHistories()->count());$this->expectException(ValidationException::class);app(OpportunityWorkflowService::class)->moveToStage($actor,$closed,$contacted); }
 public function test_checklist_completion_and_cross_company_stage_injection_are_protected(): void { $company=$this->company('A');$other=$this->company('B');$actor=$this->user($company,$this->permissions());$lead=$this->intake($actor,['contact_result'=>'called'])['lead'];$opp=$this->opportunity($actor,$lead,['budget_max'=>150000]);$contacted=$opp->pipeline->stages()->where('code','contacted')->firstOrFail();$opp=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$contacted);$requirement=CrmStageRequirement::withoutGlobalScopes()->create(['company_id'=>$company->id,'pipeline_stage_id'=>$contacted->id,'key'=>'manager_check','label'=>'Manager checked','requirement_type'=>CrmRequirementType::ChecklistCompleted->value,'is_required'=>true,'is_active'=>true]);$qualified=$opp->pipeline->stages()->where('code','qualified')->firstOrFail();try{app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$qualified);$this->fail('Checklist requirement was bypassed.');}catch(ValidationException){$this->assertTrue(true);}app(OpportunityWorkflowService::class)->completeRequirement($actor,$opp,$requirement);$moved=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$qualified);$this->assertSame($qualified->id,$moved->pipeline_stage_id);$otherActor=$this->user($other,$this->permissions());$otherLead=$this->intake($otherActor)['lead'];$otherOpp=$this->opportunity($otherActor,$otherLead);$this->expectException(ValidationException::class);app(OpportunityWorkflowService::class)->moveToStage($actor,$moved,$otherOpp->stage); }
 public function test_an_open_stage_checklist_is_completed_after_entering_that_stage_and_before_leaving_it(): void { $company=$this->company('A');$actor=$this->user($company,$this->permissions());$lead=$this->intake($actor,['contact_result'=>'called'])['lead'];$opp=$this->opportunity($actor,$lead,['budget_max'=>150000]);$pipeline=$opp->pipeline;$contacted=$pipeline->stages()->where('code','contacted')->firstOrFail();$opp=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$contacted);$qualified=$pipeline->stages()->where('code','qualified')->firstOrFail();$checklist=CrmStageRequirement::withoutGlobalScopes()->create(['company_id'=>$company->id,'pipeline_stage_id'=>$qualified->id,'key'=>'manager_approved','label'=>'Manager approved','requirement_type'=>CrmRequirementType::ChecklistCompleted->value,'is_required'=>true,'is_active'=>true]);$opp=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$qualified);$this->assertSame($qualified->id,$opp->pipeline_stage_id);$viewing=$pipeline->stages()->where('code','viewing')->firstOrFail();try{app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$viewing);$this->fail('The current Stage checklist was bypassed.');}catch(ValidationException $exception){$this->assertStringContainsString('Manager approved', $exception->errors()['stage'][0]);$this->assertStringContainsString('Open this Opportunity', $exception->errors()['stage'][0]);}app(OpportunityWorkflowService::class)->completeRequirement($actor,$opp,$checklist,'Approved by sales manager');$this->assertSame($viewing->id,app(OpportunityWorkflowService::class)->moveToStage($actor,$opp->fresh(),$viewing)->pipeline_stage_id); }
 public function test_an_open_opportunity_can_move_back_for_rework_without_bypassing_terminal_rules(): void { $company=$this->company('A');$actor=$this->user($company,$this->permissions());$lead=$this->intake($actor,['contact_result'=>'called'])['lead'];$opp=$this->opportunity($actor,$lead,['budget_max'=>150000]);$pipeline=$opp->pipeline;$new=$pipeline->stages()->where('code','new')->firstOrFail();$contacted=$pipeline->stages()->where('code','contacted')->firstOrFail();$qualified=$pipeline->stages()->where('code','qualified')->firstOrFail();$viewing=$pipeline->stages()->where('code','viewing')->firstOrFail();$opp=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$contacted);$opp=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$qualified);$opp=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$viewing);CrmStageRequirement::withoutGlobalScopes()->create(['company_id'=>$company->id,'pipeline_stage_id'=>$viewing->id,'key'=>'viewing_complete','label'=>'Viewing completed','requirement_type'=>CrmRequirementType::ChecklistCompleted->value,'is_required'=>true,'is_active'=>true]);$movedBack=app(OpportunityWorkflowService::class)->moveToStage($actor,$opp,$new);$this->assertSame($new->id,$movedBack->pipeline_stage_id);$this->assertSame('moved_back',$movedBack->stageHistories()->first()->metadata['event']); }
 public function test_permissions_are_enforced_server_side(): void { $company=$this->company('A');$actor=$this->user($company);$this->expectException(AuthorizationException::class);$this->intake($actor); }
}
